export async function fetchTransferRequests(
  status?: string
): Promise<TransferRequestWithDetails[]> {
  const supabase = createClient();
  let query = (supabase as any)
    .from("transfer_requests")
    .select(
      `*,
      origin:stores!origin_location_id ( id, name ),
      destination:stores!destination_location_id ( id, name, transfer_schedule_day ),
      variant:products!variant_id ( id, item_name ),
      requester:employees!requested_by ( id, name ),
      approver:employees!approved_by ( id, name )`
    )
    .order("created_at", { ascending: false });
  if (status) query = query.eq("status", status);
  const { data, error } = await query;
  if (error) {
    console.error("fetchTransferRequests error", error);
    return [];
  }
  const rows = (data as unknown as TransferRequestWithDetails[]) ?? [];

  // journey_mismatch requests point at a sleep_journeys row via
  // source_reference_id (no FK — the column is polymorphic), so pull the
  // order numbers in a second batched read.
  const journeyIds = Array.from(
    new Set(
      rows
        .filter((r) => r.source_type === "journey_mismatch" && r.source_reference_id)
        .map((r) => r.source_reference_id as string)
    )
  );
  if (journeyIds.length === 0) return rows;

  const { data: journeys, error: journeyError } = await (supabase as any)
    .from("sleep_journeys")
    .select("id, journey_number")
    .in("id", journeyIds);
  if (journeyError) {
    console.error("fetchTransferRequests journey numbers error", journeyError);
    return rows;
  }
  const numberById = new Map<string, string | null>(
    ((journeys as any[]) ?? []).map((j) => [j.id, j.journey_number ?? null])
  );
  return rows.map((r) =>
    r.source_type === "journey_mismatch" && r.source_reference_id
      ? { ...r, journey_number: numberById.get(r.source_reference_id) ?? null }
      : r
  );
}

export async function fetchTransfers(
  status?: string
): Promise<TransferWithDetails[]> {
  const supabase = createClient();
  let query = (supabase as any)
    .from("transfers")
    .select(
      `*,
      origin:stores!origin_location_id ( id, name ),
      destination:stores!destination_location_id ( id, name, transfer_schedule_day ),
      line_items:transfer_line_items!transfer_id (
        id, transfer_id, variant_id, quantity_requested, quantity_shipped, quantity_received,
        reported_quantity_received, reported_reason, reported_note, reported_by, reported_at,
        reporter:employees!reported_by ( id, name ),
        variant:products!variant_id ( id, item_name ),
        picks:transfer_line_units ( unit_id, unit_number, picked_requirement_id, received_at, missing_at )
      )`
    )
    .order("created_at", { ascending: false });
  if (status) query = query.eq("status", status);
  const { data, error } = await query;
  if (error) {
    console.error("fetchTransfers error", error);
    return [];
  }
  const rows = (data as unknown as TransferWithDetails[]) ?? [];

  // Cancellation reason/actor live only in audit_events (migration 118);
  // pull them for cancelled rows so the list can show who cancelled and why.
  const cancelledIds = rows
    .filter((t) => t.status === "cancelled")
    .map((t) => t.id);
  if (cancelledIds.length === 0) return rows;

  const { data: events, error: auditError } = await (supabase as any)
    .from("audit_events")
    .select(
      "entity_id, occurred_at, after, actor:employees!actor_employee_id ( id, name )"
    )
    .eq("event_type", "TRANSFER_CANCELLED")
    .in("entity_id", cancelledIds)
    .order("occurred_at", { ascending: false });
  if (auditError) {
    console.error("fetchTransfers audit_events error", auditError);
    return rows;
  }

  const byTransfer = new Map<
    string,
    { at: string; by: string | null; reason: string | null }
  >();
  for (const ev of (events as any[]) ?? []) {
    if (byTransfer.has(ev.entity_id)) continue;
    byTransfer.set(ev.entity_id, {
      at: ev.occurred_at,
      by: ev.actor?.name ?? null,
      reason: ev.after?.reason ?? null,
    });
  }
  return rows.map((t) => {
    const c = byTransfer.get(t.id);
    return c
      ? {
          ...t,
          cancelled_at: c.at,
          cancelled_by_name: c.by,
          cancel_reason: c.reason,
        }
      : t;
  });
}

async function insertTransferRequest(payload: {
  origin_location_id: string;
  destination_location_id: string;
  variant_id: string;
  quantity: number;
  source_type: "manual" | "manager_requested";
  source_reference_id?: string | null;
  request_group_id?: string | null;
}) {
  const supabase = createClient();
  const {
    data: { session },
  } = await supabase.auth.getSession();
  if (!session?.user) throw new Error("Not authenticated");

  const employee = await fetchCurrentEmployee();
  if (!employee) throw new Error("Employee record not found");

  // Validate origin has enough available Prime stock before creating the request.
  const [
    { data: position },
    { data: store },
    { data: product },
  ] = await Promise.all([
    (supabase as any)
      .from("inventory_positions_public")
      .select("ats")
      .eq("variant_id", payload.variant_id)
      .eq("location_id", payload.origin_location_id)
      .eq("disposition", "Prime")
      .is("sublocation_id", null)
      .maybeSingle(),
    (supabase as any)
      .from("stores")
      .select("name")
      .eq("id", payload.origin_location_id)
      .maybeSingle(),
    (supabase as any)
      .from("products")
      .select("item_name")
      .eq("id", payload.variant_id)
      .maybeSingle(),
  ]);

  const available = position?.ats ?? 0;
  if (payload.quantity > available) {
    throw new Error(
      `Origin "${store?.name ?? payload.origin_location_id}" only has ${available} units of "${
        product?.item_name ?? payload.variant_id
      }" available; requested ${payload.quantity}.`
    );
  }

  const { error } = await (supabase as any).from("transfer_requests").insert({
    origin_location_id: payload.origin_location_id,
    destination_location_id: payload.destination_location_id,
    variant_id: payload.variant_id,
    quantity: payload.quantity,
    source_type: payload.source_type,
    source_reference_id: payload.source_reference_id ?? null,
    status: "pending_approval",
    requested_by: employee.id,
    approved_by: null,
    approved_at: null,
    transfer_id: null,
    request_group_id: payload.request_group_id ?? null,
  });

  if (error) throw new Error(error.message);
}

